(() => {
'use strict';const $=s=>document.querySelector(s),core=window.AbsoluteLesson;
function math(host,tex){const e=document.createElement('span');e.dataset.tex=tex;host.replaceChildren(e);}
const pct=x=>(x+8)*100/16,fmt=x=>String(x).replace('.','{,}'),symbols={'=':'=','<':'<','<=':'\\le','>':'>','>=':'\\ge'};
function line(result,a,x){const row=document.createElement('div'),track=document.createElement('div');row.className='compound-line';track.className='compound-track absolute-track';track.setAttribute('role','img');track.setAttribute('aria-label',`Garis solusi, pusat ${a}, nilai uji ${x}. Interval solusi ditulis di bawah gambar.`);for(let n=-6;n<=6;n+=2){const tick=document.createElement('span');tick.className='compound-tick';tick.dataset.tex=String(n);tick.style.left=pct(n)+'%';tick.setAttribute('aria-hidden','true');track.append(tick);}for(const i of result){if(i.lo<i.hi){const band=document.createElement('span');band.className='compound-band';band.style.left=pct(Math.max(-8,i.lo))+'%';band.style.width=(Math.min(8,i.hi)-Math.max(-8,i.lo))*100/16+'%';track.append(band);}const ends=i.lo===i.hi?[[i.lo,true]]:[[i.lo,i.lc],[i.hi,i.hc]];for(const [v,closed] of ends){if(Number.isFinite(v)){const end=document.createElement('span');end.className='compound-end'+(closed?' closed':'');end.style.left=pct(v)+'%';track.append(end);}else{const arrow=document.createElement('span');arrow.className='compound-arrow '+(v<0?'left':'right');track.append(arrow);}}}if(!result.length){const empty=document.createElement('span');empty.className='compound-empty';empty.textContent='Tidak ada nilai yang memenuhi';track.append(empty);}for(const [value,cls] of [[a,'absolute-center-mark'],[x,'compound-trial']]){const marker=document.createElement('span');marker.className=cls;marker.style.left=pct(value)+'%';track.append(marker);}row.append(track);return row;}
function draw(){const a=Number($('#absolute-center').value),r=Number($('#absolute-radius').value),relation=$('#absolute-relation').value,x=Number($('#absolute-trial').value),result=core.solve(a,r,relation),accept=core.accepts(a,r,relation,x);$('#center-output').value=a;$('#radius-output').value=r;$('#absolute-trial-output').value=String(x).replace('.',',');const expression=a<0?`x+${-a}`:a===0?'x':`x-${a}`;math($('#absolute-equation'),`|${expression}|${symbols[relation]}${r}`);math($('#absolute-result'),`S=${core.intervalTex(result)}`);math($('#absolute-distance'),`|${fmt(x)}-(${a})|=${fmt(Math.abs(x-a))}`);$('#absolute-line').replaceChildren(line(result,a,x));const reason=r<0?'Batas ruas kanan negatif, sedangkan jarak tidak negatif. ':r===0?'Batas ruas kanan nol; periksa apakah jarak nol termasuk. ':'Bandingkan jarak sebenarnya dengan batas pada ruas kanan. ';$('#absolute-feedback').textContent=reason+`Nilai uji ${String(x).replace('.',',')} berjarak ${String(Math.abs(x-a)).replace('.',',')} dari pusat ${a}; ${accept?'memenuhi':'tidak memenuhi'} hubungan yang dipilih.`;}
for(const id of ['absolute-center','absolute-radius','absolute-trial'])$('#'+id).addEventListener('input',draw);$('#absolute-relation').addEventListener('change',draw);
function preset(relation,r){$('#absolute-center').value=2;$('#absolute-radius').value=r;$('#absolute-relation').value=relation;$('#absolute-trial').value=0;draw();}
$('#inside-example').addEventListener('click',()=>preset('<',3));$('#outside-example').addEventListener('click',()=>preset('>',3));$('#zero-example').addEventListener('click',()=>{preset('<=',0);$('#absolute-trial').value=2;draw();});$('#negative-example').addEventListener('click',()=>preset('>',-1));$('#absolute-reset').addEventListener('click',()=>preset('=',3));draw();
const questions=[
[String.raw`|x-2|=3`,[String.raw`\{-1,5\}`,String.raw`\{5\}`,String.raw`[-1,5]`],0,'Kedua titik berjarak tiga dari dua. Persamaan meminta jarak tepat, bukan semua titik di antaranya.'],
[String.raw`|2x-1|=5`,[String.raw`\{-2,3\}`,String.raw`\{-3,2\}`,String.raw`\{3\}`],0,'Isi mutlak sama dengan lima atau negatif lima. Kedua persamaan linear menghasilkan tiga dan negatif dua.'],
[String.raw`|x+1|\le2`,[String.raw`(-3,1)`,String.raw`[-3,1]`,String.raw`(-\infty,-3]\cup[1,\infty)`],1,'Pusatnya negatif satu. Jarak paling banyak dua memberi daerah di dalam dengan kedua batas ikut.'],
[String.raw`|x-2|>3`,[String.raw`(-1,5)`,String.raw`[-1,5]`,String.raw`(-\infty,-1)\cup(5,\infty)`],2,'Jarak lebih dari tiga memberi dua daerah di luar. Kedua titik batas tidak ikut.'],
[String.raw`|x-2|<0`,[String.raw`\{2\}`,String.raw`\varnothing`,String.raw`\mathbb R`],1,'Jarak tidak mungkin lebih kecil dari nol. Bahkan pusat memberi jarak tepat nol, bukan kurang dari nol.'],
[String.raw`|x-2|\ge-1`,[String.raw`\varnothing`,String.raw`\{2\}`,String.raw`\mathbb R`],2,'Setiap jarak tidak negatif, sehingga selalu lebih besar dari atau sama dengan negatif satu.'],
[String.raw`|x+1|\le0`,[String.raw`\{-1\}`,String.raw`\{0\}`,String.raw`\varnothing`],0,'Jarak tidak negatif dan paling banyak nol berarti tepat nol. Hanya pusat negatif satu yang memenuhi.'],
[String.raw`|2x+1|<3`,[String.raw`(-2,1)`,String.raw`(-\infty,-2)\cup(1,\infty)`,String.raw`[-2,1]`],0,'Tulis negatif tiga kurang dari dua kali masukan ditambah satu, dan hasil itu kurang dari tiga. Kurangi satu dan bagi dua pada ketiga bagian.']
];const solved=new Set();questions.forEach(([tex,options,answer,reason],i)=>{const box=document.createElement('fieldset'),legend=document.createElement('legend'),num=document.createElement('span'),formula=document.createElement('span');num.dataset.noEquation='';num.textContent=`Latihan ${i+1}: `;formula.dataset.tex=tex;legend.append(num,formula);box.append(legend);options.forEach((option,j)=>{const label=document.createElement('label'),radio=document.createElement('input'),copy=document.createElement('span');radio.type='radio';radio.name=`absolute-q${i}`;radio.value=String(j);copy.dataset.tex=option;label.append(radio,copy);box.append(label);});const button=document.createElement('button');button.type='button';button.textContent='Periksa jawaban';const feedback=document.createElement('p');feedback.setAttribute('role','status');button.addEventListener('click',()=>{const selected=box.querySelector('input:checked');if(!selected){feedback.textContent='Pilih satu jawaban terlebih dahulu.';return;}const ok=Number(selected.value)===answer;if(ok)solved.add(i);feedback.textContent=(ok?'Tepat. ':'Belum tepat. ')+reason;feedback.className=ok?'correct':'incorrect';$('#absolute-progress').textContent=`${solved.size} dari 8 latihan pernah dijawab tepat.`;});box.addEventListener('change',()=>{feedback.textContent='Jawaban berubah. Periksa kembali untuk melihat tanggapan.';feedback.className='';});box.append(button,feedback);$('#absolute-questions').append(box);});$('#absolute-progress').textContent='0 dari 8 latihan pernah dijawab tepat.';
try{$('#absolute-reflection').value=localStorage.getItem('fondasi-absolute-reflection')||'';}catch{$('#absolute-save').textContent='Catatan belum dapat dimuat. Salin bila diperlukan.';}$('#absolute-reflection').addEventListener('input',()=>{try{localStorage.setItem('fondasi-absolute-reflection',$('#absolute-reflection').value);$('#absolute-save').textContent='Catatan tersimpan di peramban ini.';}catch{$('#absolute-save').textContent='Catatan belum dapat disimpan. Salin bila diperlukan.';}});
})();
